191	  public void integrate(final ExpandableStatefulODE equations, final double t)
192	      throws MathIllegalStateException, MathIllegalArgumentException {
193	
194	    sanityChecks(equations, t);
195	    setEquations(equations);
196	    final boolean forward = t > equations.getTime();
197	
198	    // create some internal working arrays
199	    final double[] y0  = equations.getCompleteState();
200	    final double[] y = y0.clone();
201	    final int stages = c.length + 1;
202	    final double[][] yDotK = new double[stages][y.length];
203	    final double[] yTmp    = y0.clone();
204	    final double[] yDotTmp = new double[y.length];
205	
206	    // set up an interpolator sharing the integrator arrays
207	    final RungeKuttaStepInterpolator interpolator = (RungeKuttaStepInterpolator) prototype.copy();
208	    interpolator.reinitialize(this, yTmp, yDotK, forward,
209	                              equations.getPrimaryMapper(), equations.getSecondaryMappers());
210	    interpolator.storeTime(equations.getTime());
211	
212	    // set up integration control objects
213	    stepStart         = equations.getTime();
214	    double  hNew      = 0;
215	    boolean firstTime = true;
216	    initIntegration(equations.getTime(), y0, t);
217	
218	    // main integration loop
219	    isLastStep = false;
220	    do {
221	
222	      interpolator.shift();
223	
224	      // iterate over step size, ensuring local normalized error is smaller than 1
225	      double error = 10;
226	      while (error >= 1.0) {
227	
228	        if (firstTime || !fsal) {
229	          // first stage
230	          computeDerivatives(stepStart, y, yDotK[0]);
231	        }
232	
233	        if (firstTime) {
234	          final double[] scale = new double[mainSetDimension];
235	          if (vecAbsoluteTolerance == null) {
236	              for (int i = 0; i < scale.length; ++i) {
237	                scale[i] = scalAbsoluteTolerance + scalRelativeTolerance * FastMath.abs(y[i]);
238	              }
239	          } else {
240	              for (int i = 0; i < scale.length; ++i) {
241	                scale[i] = vecAbsoluteTolerance[i] + vecRelativeTolerance[i] * FastMath.abs(y[i]);
242	              }
243	          }
244	          hNew = initializeStep(forward, getOrder(), scale,
245	                                stepStart, y, yDotK[0], yTmp, yDotK[1]);
246	          firstTime = false;
247	        }
248	
249	        stepSize = hNew;
250	
251	        // next stages
252	        for (int k = 1; k < stages; ++k) {
253	
254	          for (int j = 0; j < y0.length; ++j) {
255	            double sum = a[k-1][0] * yDotK[0][j];
256	            for (int l = 1; l < k; ++l) {
257	              sum += a[k-1][l] * yDotK[l][j];
258	            }
259	            yTmp[j] = y[j] + stepSize * sum;
260	          }
261	
262	          computeDerivatives(stepStart + c[k-1] * stepSize, yTmp, yDotK[k]);
263	
264	        }
265	
266	        // estimate the state at the end of the step
267	        for (int j = 0; j < y0.length; ++j) {
268	          double sum    = b[0] * yDotK[0][j];
269	          for (int l = 1; l < stages; ++l) {
270	            sum    += b[l] * yDotK[l][j];
271	          }
272	          yTmp[j] = y[j] + stepSize * sum;
273	        }
274	
275	        // estimate the error at the end of the step
276	        error = estimateError(yDotK, y, yTmp, stepSize);
